$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$r="$env:LOCALAPPDATA\npu-render"
$interruption=Get-Content "$r/vm/complex-batch-interruption-v1/report.json" -Raw|ConvertFrom-Json
if($interruption.replay_rows -ne 55 -or $interruption.active_renderers -ne 0){throw 'Missing interruption proof'}
if((Get-FileHash "$r/vm/ptl-worker-v29-qualification/report.json").Hash.ToLower() -ne $interruption.qualification_report_sha256){throw 'Interrupted report changed'}
$q=Get-Content "$r/vm/ptl-worker-v28-qualification/report.json" -Raw|ConvertFrom-Json
if(!$q.completed -or $q.passed){throw 'Rejected attempt incomplete'}
function Item([string]$name,[string]$path,[string]$remote){
 if(!(Test-Path $path)){throw "Missing evidence: $name"}
 $stream=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
 try{$h=(Get-FileHash -InputStream $stream).Hash}finally{$stream.Dispose()}
 [ordered]@{source=$name;remote_source=$remote;bytes=(Get-Item $path).Length;sha256=$h}
}
$items=@(
foreach($name in @('ptl-worker-v28-qualification','ptl-native-worker-v28-selected','complex-batch-provider-recovery-v1-qualification','ptl-worker-v29-qualification','ptl-native-worker-v29-selected','ptl-native-worker-v29-full','complex-batch-provider-recovery-v2-qualification','ptl-post-batch-rejection-health-v1','complex-batch-interruption-v1')){
 if(!(Test-Path "$r\vm\$name")){continue}
 Get-ChildItem "$r\vm\$name" -File -Recurse|Where-Object {
  ($_.Extension -in @('.json','.jsonl','.log','.txt','.inf','.ps1','.py','.c','.cpp','.hpp')) -and
  ($_.Name -notlike 'client-*' -or ($_.Name -like '*.stderr.log' -and $_.Length -gt 0))
 }|ForEach-Object {
  if($_.Length -gt 30000000){throw 'Unexpected artifact size'}
  $n=$_.FullName.Substring(("$r\vm\").Length).Replace('\','/');Item $n $_.FullName ("vm/"+$n)
 }
}
foreach($name in @('build-ptl-native-worker-v28.ps1','build-ptl-native-worker-v28.log','qualify-ptl-native-worker-v28.py','run-ptl-worker-v28-qualification.ps1','ptl-native-worker-v28-source.json','ptl-worker-v28-tools-source.json','ptl-native-worker-v28/ptl_long_triangle_draw.cpp','ptl-native-worker-v28/ptl_solid.hpp','ptl-native-worker-v28/packet_provider_process.hpp','ptl-native-worker-v28/ptl_program_ir.hpp','ptl-native-worker-v28/CMakeLists.txt','ptl-native-worker-v28/ptl_four_tap.hpp','ptl-native-worker-v28/ptl_masked_triangle_draw.cpp','ptl-native-worker-v28/ptl_triangle_texture_draw.cpp','ptl-native-worker-v28/ptl_resident_clip.hpp','ptl-native-worker-v28/local_indexed_worker.cpp','ptl-native-worker-v28/ptl_complex_shader.hpp','ptl-native-worker-v28/ptl_geometry_triangle_draw.cpp','ptl-native-worker-v28/ptl_long_shaders.hpp','ptl-native-worker-v28/ptl_resident_clip_triangle_draw.hpp','ptl-native-worker-v28/ptl_four_tap_shaders.hpp','ptl-native-worker-v28/ptl_masked.hpp','ptl-native-worker-v28/ptl_program_triangle_draw.hpp','ptl-native-worker-v28/ptl_complex_triangle_draw.cpp','ptl-native-worker-v28/indexed_pipeline.hpp','ptl-native-worker-v28/ptl_long_shader.hpp','ptl-native-worker-v28/ptl_triangle_texture_draw.hpp','ptl-native-worker-v28/ptl_adaptive_triangle.hpp','ptl-native-worker-v28/ptl_geometry.hpp','ptl-native-worker-v28/ptl_solid_shaders.hpp','ptl-native-worker-v28/ptl_geometry_triangle_draw.hpp','ptl-native-worker-v28/ptl_masked_shaders.hpp','ptl-native-worker-v28/ptl_resident_clip_triangle_draw.cpp','ptl-native-worker-v28/local_indexed_validated_client.hpp','ptl-native-worker-v28/ptl_program_triangle_draw.cpp','ptl-native-worker-v28/ptl_complex_triangle_draw.hpp','ptl-native-worker-v28/npu_turbo_import.hpp','ptl-native-worker-v28/ptl_quad_batch.hpp','ptl-native-worker-v28/ptl_long_triangle_draw.hpp','ptl-native-worker-v28/ptl_point_rectangle.hpp','ptl-native-worker-v28/ptl_program.hpp','ptl-native-worker-v28/ptl_texture_shader.hpp','ptl-native-work