e_draw.hpp','ptl-native-worker-v29/ptl_point_rectangle.hpp','ptl-native-worker-v29/ptl_program.hpp','ptl-native-worker-v29/ptl_texture_shader.hpp','ptl-native-worker-v29/ptl_masked_triangle_draw.hpp','ptl-native-worker-v29/response_envelope_v1.hpp','ptl-native-worker-v29/ptl_complex_shaders.hpp','ptl-native-worker-v29/ptl_texture_shaders.hpp','qualify-complex-batch-comparison-v1.py','qualify-complex-batch-provider-recovery-v1.py','run-complex-batch-provider-recovery-v1-qualification.ps1','complex-batch-recovery-v1-source.json','qualify-complex-batch-comparison-v2.py','qualify-complex-batch-provider-recovery-v2.py','run-complex-batch-provider-recovery-v2-qualification.ps1','complex-batch-recovery-v2-source.json','verify-ptl-post-batch-rejection-health-v1.py')){
 Item $name "$r\vm\$name" ("vm/"+$name)
}
foreach($version in @(28,29)){foreach($file in @('build-report.json','registered-build-report.json')){
 $name="ptl-native-worker-v$version"
 if(Test-Path "$r\builds\$name\$file"){Item "build-$name/$file" "$r\builds\$name\$file" "builds/$name/$file"}
}}
);$items|ConvertTo-Json -Depth 5
